@import "../../shared/tokens.css";

/* plan-doc: only what DESIGN.md does not cover, tokens only. */

.plan-notice { margin-bottom: var(--space-md); }

.plan-layout { display: grid; gap: var(--space-lg); align-items: start; }
@media (min-width: 60rem) {
  .plan-layout { grid-template-columns: minmax(0, 360px) minmax(0, 1fr); }
}
.plan-inputs { display: grid; gap: var(--space-md); min-width: 0; }

/* decision picker rows: hairlines between, no boxes */
.pick-list { display: grid; margin: 0; padding: 0; list-style: none; }
.pick { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--space-2xs) var(--space-sm); padding-block: var(--space-sm); border-bottom: var(--rule-hair) solid var(--color-rule); }
.pick:first-child { padding-top: 0; }
.pick:last-child { border-bottom: 0; padding-bottom: 0; }
.pick > input { width: 18px; height: 18px; margin: var(--space-3xs) 0 0; cursor: pointer; }
.pick > input:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }
.pick--plain { grid-template-columns: minmax(0, 1fr) auto; align-items: center; }
.pick__text { display: grid; gap: var(--space-3xs); min-width: 0; cursor: pointer; }
.pick--plain .pick__text { cursor: default; }
.pick__title { font-size: var(--text-sm); font-weight: 600; line-height: 1.4; }
.pick__preview { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; color: var(--color-ink-2); font-size: var(--text-sm); line-height: 1.5; }
.pick__source { color: var(--color-muted); font-size: var(--text-xs); }
.pick__actions { grid-column: 2; display: flex; gap: var(--space-2xs); margin-left: calc(var(--space-sm) * -1); }

.add-form { display: grid; gap: var(--space-sm); margin-bottom: var(--space-md); padding-bottom: var(--space-md); border-bottom: var(--rule-hair) solid var(--color-rule); }
.input--file { height: auto; padding: var(--space-xs) var(--space-sm); font-size: var(--text-sm); }
.input--file::file-selector-button { margin-right: var(--space-sm); padding: var(--space-2xs) var(--space-sm); border: var(--rule-hair) solid var(--color-rule-2); border-radius: var(--radius-mark); background: var(--color-key-face); color: var(--color-ink); font: inherit; cursor: pointer; }

.plan-step1 { display: grid; justify-items: start; gap: var(--space-sm); }
.plan-step1__list { width: 100%; }
.plan-step1__list a { color: var(--color-accent-text); }

/* image tiles: a well, a caption, a quiet foot. The chosen tile gets an accent ring plus the checked box. */
.tile { position: relative; display: grid; gap: var(--space-2xs); }
.tile__check { position: absolute; z-index: var(--z-raised); top: var(--space-xs); left: var(--space-xs); width: 18px; height: 18px; margin: 0; cursor: pointer; }
.tile__check:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 2px; }
.tile__label { display: grid; gap: var(--space-2xs); min-width: 0; cursor: pointer; }
.tile:has(.tile__check:checked) .preview__media { outline: 2px solid var(--color-accent); outline-offset: -2px; }
.tile:not(:has(.tile__check:checked)) .preview__media img { opacity: 0.6; }
.tile__foot { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2xs); min-width: 0; }
.tile__del { margin-right: calc(var(--space-xs) * -1); }

.plan-go { display: grid; justify-items: start; gap: var(--space-xs); }

/* document panel */
.doc-panel { min-width: 0; }
.doc-panel__head { flex-wrap: wrap; }
.doc-panel__title { display: grid; gap: var(--space-3xs); min-width: 0; }
.doc-panel__title .panel__title { overflow-wrap: break-word; }
.doc-tabbar { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: var(--space-xs) var(--space-md); border-bottom: var(--rule-hair) solid var(--color-rule); }
.doc-tabbar .tabs { border-bottom: 0; }
.doc-save { padding-bottom: var(--space-xs); }
.doc-skeleton { display: grid; gap: var(--space-sm); max-width: 72ch; }
.doc-editor__area { min-height: 60dvh; }
.doc-split { display: grid; gap: var(--space-lg); }
@media (min-width: 75rem) {
  .doc-split { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: start; }
  .doc-split__preview { max-height: calc(60dvh + var(--space-2xl)); overflow-y: auto; padding-right: var(--space-xs); }
}

.doc-versions { display: grid; align-items: start; gap: var(--space-xs); }
.doc-versions__title { font-size: var(--text-sm); font-weight: 600; letter-spacing: 0; }
.doc-versions__list { display: grid; margin: 0; padding: 0; list-style: none; }
