7	export default async function Page({ searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> }) {
8	  const sp = await searchParams;
9	  const wf = typeof sp.workflow === 'string' && sp.workflow.length <= 200 ? sp.workflow : null;
10	  // Import on load so the hand-off link from workflow-view lands with its cards already selected (idempotent).
11	  const imported = wf ? importWorkflow(wf) : null;
12	  const docs = listDocs();
13	  const latest = docs[0] ? (store().prepare('SELECT * FROM plan_docs WHERE id = ?').get(docs[0].id) as DocRow) : null;
14	  // node:sqlite rows have a null prototype; structuredClone makes them plain objects a Client Component accepts.
15	  const props = structuredClone({ initialInputs: listInputs(), initialDocs: docs, initialDoc: latest ?? null, step1: listStep1(), imported });
16	  return <PlanDoc {...props} />;
17	}

