S=/private/tmp/claude-501/-Users-jyl-work-repo-ai-agent-live-super-planer/0b348ffc-6a36-4420-b451-05e59d38b9e3/scratchpad; mkdir -p $S/cdp; cat > $S/cdp/drive.mjs <<'EOF'
// Drives the plan-doc page through Chrome DevTools Protocol (Node global WebSocket).
const port = process.argv[2];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let list;
for (let i = 0; i < 40; i++) { try { list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); if (list.some((t) => t.type === 'page')) break; } catch {} await sleep(250); }
const page = list.find((t) => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener('open', r));
let id = 0; const pending = new Map(); const logs = [];
ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } if (m.method === 'Runtime.consoleAPICalled' || m.method === 'Runtime.exceptionThrown') logs.push(JSON.stringify(m.params).slice(0, 300)); });
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); return r.result?.result?.value ?? r.result?.exceptionDetails?.text; };
await send('Runtime.enable'); await send('Page.enable');
await send('Page.navigate', { url: 'http://localhost:3103/' }); await sleep(2500);
const click = (sel, text) => ev(`(() => { const el = [...document.querySelectorAll(${JSON.stringify(sel)})].find(e => ${text ? `e.textContent.includes(${JSON.stringify(text)})` : 'true'}); if (!el) return 'missing'; el.click(); return 'ok'; })()`);
console.log('tabs', await ev(`[...document.querySelectorAll('[role=tab]')].map(t => t.textContent + ':' + t.getAttribute('aria-selected') + ':' + t.tabIndex).join(' ')`));
console.log('preview imgs', await ev(`[...document.querySelectorAll('.md-doc figure img')].map(i => i.complete && i.naturalWidth > 0).join(',')`));
console.log('figcaptions', await ev(`document.querySelectorAll('.md-doc figcaption').length`));
console.log('table', await ev(`document.querySelectorAll('.md-doc table tr').length`));
// keyboard: ArrowRight on the selected tab
await ev(`document.querySelector('[role=tab][aria-selected=true]').focus()`);
await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'ArrowRight', code: 'ArrowRight', windowsVirtualKeyCode: 39 }); await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'ArrowRight', code: 'ArrowRight', windowsVirtualKeyCode: 39 }); await sleep(300);
console.log('after ArrowRight', await ev(`document.activeElement.textContent + ' selected=' + document.activeElement.getAttribute('aria-selected')`), 'textarea', await ev(`!!document.querySelector('#doc-md')`));
console.log('split', await click('[role=tab]', '나란히')); await sleep(300);
console.log('split has both', await ev(`!!document.querySelector('.doc-split #doc-md') && !!document.querySelector('.doc-split .md-doc')`));
// type into the editor through React's value setter
await ev(`(() => { const ta = document.querySelector('#doc-md'); const set = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set; set.call(ta, ta.value.replace('## 개요', '## 개요\\n\\n> CDP 편집 확인')); ta.dispatchEvent(new Event('input', { bubbles: true })); })()`);
await sleep(200);
console.log('live preview', await ev(`document.querySelector('.doc-split .md-doc blockquote')?.textContent`), 'status', await ev(`document.querySelector('.doc-save').textContent`));
await sleep(1800);
console.log('status after debounce', await ev(`document.querySelector('.doc-save').textContent`));
// uncheck one decision, generate
console.log('uncheck', await ev(`(() => { const c = document.querySelector('.pick input[type=checkbox]'); c.click(); return c.checked; })()`));
console.log('generate', await click('.btn--primary', '기획서 만들기')); await sleep(1500);
console.log('versions', await ev(`document.querySelectorAll('.version').length`), 'current tab', await ev(`document.querySelector('[role=tab][aria-selected=true]').textContent`));
// reopen previous version
console.log('reopen', await ev(`(() => { const v = document.querySelectorAll('.version')[1]; v.click(); return v.textContent; })()`)); await sleep(800);
console.log('reopened has edit', await ev(`document.querySelector('.md-doc blockquote')?.textContent`));
// add + edit decision form
console.log('add', await click('.panel__actions .btn', '추가'));
await sleep(200);
console.log('form', await ev(`!!document.querySelector('form[aria-label="결정 문서 추가"]')`));
console.log('step1 toggle', await click('.plan-step1 .btn', 'Step1')); await sleep(700);
console.log('step1 list', await ev(`document.querySelector('#step1-list')?.textContent.slice(0, 80)`));
console.log('console/exceptions', logs.length ? logs : 'none');
ws.close(); process.exit(0);
EOF
